/// Intent-based model roles with ordered fallback chains and path-scoped
/// overrides — the configuration half of the model-roles feature.
///
/// Ported (reduced) from oh-my-pi `packages/coding-agent/src/config/
/// model-resolver.ts` and `model-roles.ts`. Deliberate reductions:
///
/// - Only the four card-mandated roles exist here: `default`, `smol`, `slow`,
///   `plan` (exact omp names). omp's `vision`/`designer`/`commit`/`tiny`/
///   `task`/`advisor` roles and its fuzzy catalog matching (`matchModel`,
///   thinking suffixes, `@upstream` routing) are not ported; our chains name
///   concrete `provider/modelId` entries resolved against the small
///   [provider catalog](provider_catalog.dart).
/// - Role inheritance is simplified to omp's
///   `shouldInheritDefaultBeforePriority` behavior: an unset non-default role
///   resolves through the `default` role's chain.
/// - Path-scoped overrides follow omp's scoped `enabledModels` semantics
///   (entry applies when the cwd is the configured path or a subdirectory),
///   extended with glob patterns (`*`, `**`) as the card requires.
///
/// Runtime resolution, key rotation, and the fallback stream live in the
/// sibling files of this directory; this file is pure configuration:
/// parsing, validation, serialization, and chain selection.
library;

import 'dart:convert';

import 'package:yaml/yaml.dart';

import '../exceptions.dart';
import '../providers/provider_tuning.dart' show parseProviderTimeoutMs;
import '../providers/thinking.dart';
import '../utils/path_text.dart';
import 'provider_catalog.dart'
    show catalogProvider, parseAuthHeaderName, validateAuthHeaderDialect;

/// The model roles supported by [ModelRolesConfig], in declaration order.
///
/// Exact omp role names (`default`, `smol`, `slow`, `plan`) plus the
/// harness-local `subagent` delegation role.
const modelRoleIds = ['default', 'smol', 'slow', 'plan', 'subagent', 'memory'];

/// The role used for ordinary agent runs.
const defaultModelRole = 'default';

/// The role compaction summarization resolves through when configured.
const smolModelRole = 'smol';

/// The role long-term-memory LLM work (consolidation, semantic search)
/// resolves through when configured. Falls back to `smol`, then the main
/// model — the memory call shapes match the smol cost class.
const memoryModelRole = 'memory';

/// The role spawned subagents resolve through when configured (items
/// without a specialist role — `explore` keeps `smol`, `review` keeps
/// `slow`). Falls back to the parent model when unset.
const subagentModelRole = 'subagent';

/// One entry of a role's fallback chain: a concrete model plus an optional
/// API-key base-name override.
final class ModelRef {
  /// Creates a model reference.
  const ModelRef({
    required this.provider,
    required this.modelId,
    this.apiKeyName,
    this.baseUrl,
    this.contextWindow,
    this.maxTokens,
    this.input,
    this.thinkingLevel,
    this.authHeader,
    this.project,
    this.connectTimeout,
    this.streamIdleTimeout,
    this.keyless = false,
  });

  /// Parses the string shorthand `provider/modelId`.
  ///
  /// Throws [ConfigException] when [value] is not `<provider>/<modelId>`
  /// with both sides non-empty.
  factory ModelRef.parse(String value, {String? role}) {
    final slash = value.indexOf('/');
    if (slash <= 0 || slash == value.length - 1) {
      throw ConfigException(
        'invalid model reference "$value"${role == null ? '' : ' in role "$role"'}'
        ' — expected "provider/modelId"',
      );
    }
    return ModelRef(
      provider: value.substring(0, slash).trim(),
      modelId: value.substring(slash + 1).trim(),
    );
  }

  /// Parses one chain entry from yaml: either the string shorthand or a map
  /// with `provider`/`model` plus optional overrides.
  factory ModelRef.fromYaml(Object? node, {String? role}) {
    switch (node) {
      case String value:
        return ModelRef.parse(value, role: role);
      case YamlMap entry:
        // Leaf reads bind to `entry` (not `map`/`doc`): the settings
        // completeness gate counts literal `map['…']` reads in parser
        // sources as TOP-LEVEL keys, and these are section leaves
        // (issue #964 review — `authHeader` tripped the ratchet).
        final provider = entry['provider'];
        final model = entry['model'];
        if (provider is! String || provider.trim().isEmpty) {
          throw ConfigException(
            'model chain entry${role == null ? '' : ' in role "$role"'} '
            'is missing a "provider" string',
          );
        }
        if (model is! String || model.trim().isEmpty) {
          throw ConfigException(
            'model chain entry${role == null ? '' : ' in role "$role"'} '
            'is missing a "model" string',
          );
        }
        final where =
            'model chain entry${role == null ? '' : ' in role "$role"'}';
        final authHeader = parseAuthHeaderName(entry['authHeader'], where);
        validateAuthHeaderDialect(authHeader, catalogProvider(provider), where);
        // The project rides the wire RAW (issue #1941): a non-Latin-1 value
        // makes Dart reject the header MID-CHAT — refuse it at parse time
        // (the codemie-code daemon omits the header instead; a chain ref
        // explicitly DEMANDS the project, so loud beats silent).
        final project = _optionalString(entry, 'project', role);
        if (project != null &&
            !RegExp(r'^[\x20-\x7E\xA0-\xFF]*$').hasMatch(project)) {
          throw ConfigException(
            '$where: "project" must be a Latin-1 '
            'header value (0x20-0x7E, 0xA0-0xFF), got: $project',
          );
        }
        final keyless = _optionalBool(entry, 'keyless', role);
        final keyName = _optionalString(entry, 'apiKeyName', role);
        if (keyless && keyName != null) {
          throw ConfigException(
            '$where: "keyless" and "apiKeyName" are mutually exclusive — '
            'a keyless endpoint takes no credential, so "$keyName" would '
            'be silently ignored',
          );
        }
        return ModelRef(
          provider: provider.trim(),
          modelId: model.trim(),
          apiKeyName: keyName,
          baseUrl: _optionalString(entry, 'baseUrl', role),
          contextWindow: _optionalInt(entry, 'contextWindow', role),
          maxTokens: _optionalInt(entry, 'maxTokens', role),
          input: _optionalInput(entry, role),
          thinkingLevel: _optionalThinkingLevel(entry, role),
          authHeader: authHeader,
          // The CodeMie project the chain bills (issue #1941): a pin
          // without it serves from the chain and bills the user's DEFAULT
          // project — the selected one is silently ignored.
          project: project,
          // Per-provider stall-recovery tuning (issue #1398): the watchdog
          // knobs ride the chain entry, same place baseUrl/keys live.
          connectTimeout: parseProviderTimeoutMs(
            entry['connectTimeoutMs'],
            'connectTimeoutMs',
            where,
          ),
          streamIdleTimeout: parseProviderTimeoutMs(
            entry['streamIdleTimeoutMs'],
            'streamIdleTimeoutMs',
            where,
          ),
          keyless: keyless,
        );
      default:
        throw ConfigException(
          'invalid model chain entry${role == null ? '' : ' in role "$role"'}: '
          'expected "provider/modelId" or a map, got ${node.runtimeType}',
        );
    }
  }

  static String? _optionalString(YamlMap map, String key, String? role) {
    final value = map[key];
    if (value == null) return null;
    if (value is! String || value.trim().isEmpty) {
      throw ConfigException(
        '"$key"${role == null ? '' : ' in role "$role"'} must be a '
        'non-empty string',
      );
    }
    return value.trim();
  }

  static int? _optionalInt(YamlMap map, String key, String? role) {
    final value = map[key];
    if (value == null) return null;
    if (value is! int || value <= 0) {
      throw ConfigException(
        '"$key"${role == null ? '' : ' in role "$role"'} must be a '
        'positive integer',
      );
    }
    return value;
  }

  /// A `keyless: true` flag (gh-1570 AC8): the entry's endpoint needs NO
  /// credential (a localhost bench server). Only `true` means keyless —
  /// absent, null and `false` all read as false.
  static bool _optionalBool(YamlMap map, String key, String? role) {
    final value = map[key];
    if (value == null) return false;
    if (value is! bool) {
      throw ConfigException(
        '"$key"${role == null ? '' : ' in role "$role"'} must be a boolean',
      );
    }
    return value;
  }

  /// The `input` modality list override (`["text","image"]`): an explicit
  /// declaration wins over the catalog spec's modalities (issue #638 —
  /// same named-error rules as the `models.custom` yaml field).
  static List<String>? _optionalInput(YamlMap node, String? role) {
    final value = node['input'];
    if (value == null) return null;
    if (value is! YamlList || value.isEmpty) {
      throw ConfigException(
        '"input"${role == null ? '' : ' in role "$role"'} must be a '
        'non-empty list of "text"/"image"',
      );
    }
    return [
      for (final entry in value)
        if (entry == 'text' || entry == 'image')
          entry as String
        else
          throw ConfigException(
            '"input"${role == null ? '' : ' in role "$role"'} entries must '
            'be "text" or "image", got: $entry',
          ),
    ];
  }

  /// The thinking-level rung override (issue #734): one of
  /// [configThinkingLevels]; `xhigh`/`max` are accepted and normalize to
  /// `high` (the same fold the wire clamp applies), anything else fails
  /// loud naming the ladder.
  static String? _optionalThinkingLevel(YamlMap node, String? role) {
    // Leaf read on `node`, not `map`: whole-config map reads (`map['…']`/
    // `doc['…']`) are the parity guard's top-level-schema signal
    // (test/parity/settings_completeness_test.dart); section leaves
    // (`node['…']`, like `input` above) stay out of that registry.
    final value = node['thinkingLevel'];
    if (value == null) return null;
    if (value is! String) {
      throw ConfigException(
        '"thinkingLevel"${role == null ? '' : ' in role "$role"'} must be '
        'one of ${configThinkingLevels.join(', ')}, got: $value',
      );
    }
    return normalizeConfigThinkingLevel(value.trim()) ??
        (throw ConfigException(
          '"thinkingLevel"${role == null ? '' : ' in role "$role"'} must be '
          'one of ${configThinkingLevels.join(', ')}, got: $value',
        ));
  }

  /// Catalog provider name (e.g. `openrouter`, `openai`, `anthropic`,
  /// `google`); see `provider_catalog.dart`.
  final String provider;

  /// The model id sent to the provider (e.g. `anthropic/claude-sonnet-4`).
  final String modelId;

  /// Base name of the API key in the secrets store. Rotation stacks
  /// `[apiKeyName]` with `[apiKeyName]_2`, `[apiKeyName]_3`, ... When null,
  /// the provider's canonical env name is used.
  final String? apiKeyName;

  /// Provider base-URL override; the catalog default is used when null.
  final String? baseUrl;

  /// Context-window override (tokens); the catalog default is used when null.
  final int? contextWindow;

  /// Max-output-token override; the catalog default is used when null.
  final int? maxTokens;

  /// Input-modality override (`["text","image"]`); the catalog spec's
  /// modalities are used when null (issue #638).
  final List<String>? input;

  /// Thinking-level override (`minimal…max`, `xhigh`/`max` normalize to
  /// `high`); the adapter default (no thinking) is used when null
  /// (issue #734).
  final String? thinkingLevel;

  /// Auth header name override (`authHeader:`, issue #964): the built model
  /// sends `<authHeader>: <key>` instead of `Authorization: Bearer <key>`.
  /// Null keeps the Bearer default.
  final String? authHeader;

  /// The CodeMie project the entry's requests bill (`project:`, issue
  /// #1941) — rides the chain model as the `x-codemie-project` header. Null
  /// keeps the backend's default-project fallback.
  final String? project;

  /// Per-provider connect/first-headers watchdog override
  /// (`connectTimeoutMs`, issue #1398). Null keeps the global
  /// `providerTimeouts:` value, then the 180 s default.
  final Duration? connectTimeout;

  /// Per-provider stream-idle watchdog override (`streamIdleTimeoutMs`,
  /// issue #1398). Null keeps the global value, then the 300 s default.
  final Duration? streamIdleTimeout;

  /// The endpoint needs NO credential (`keyless: true`, gh-1570 AC8): a
  /// localhost bench server or an unauthenticated gateway. The resolver
  /// treats the entry as always credentialed and the stream factory
  /// receives the EMPTY key — byte-parity with the non-roles keyless
  /// boot. Saved roles configs never outrank a keyless pin.
  final bool keyless;

  /// The `provider/modelId` display form.
  String get label => '$provider/$modelId';

  /// Serializes to the map form (round-trips with [ModelRef.fromYaml]).
  ///
  /// The per-field emission funnels through one [writeIf] seam: a flat,
  /// branchless field list (one line per optional field, byte-identical
  /// output) instead of an if-block per field — the block-per-field shape
  /// pushed this method past the CRAP gate with the `project:` addition
  /// (issue #1941 review).
  String toYaml() {
    final buffer = StringBuffer()
      ..write('provider: $provider\n')
      ..write('model: $modelId\n');
    void writeIf(bool present, String line) {
      if (present) buffer.write(line);
    }

    writeIf(apiKeyName != null, 'apiKeyName: $apiKeyName\n');
    writeIf(baseUrl != null, 'baseUrl: $baseUrl\n');
    writeIf(contextWindow != null, 'contextWindow: $contextWindow\n');
    writeIf(maxTokens != null, 'maxTokens: $maxTokens\n');
    writeIf(thinkingLevel != null, 'thinkingLevel: $thinkingLevel\n');
    // The `?.` interpolations build a throwaway string when the field is
    // absent — writeIf decides the EMISSION, so the null branch never
    // reaches the buffer (and `!` here would crash before the check).
    writeIf(input != null, 'input: [${input?.join(', ')}]\n');
    // RFC 7230 tokens may lead with yaml specials (`#`, `*`, `!`): a raw
    // scalar would round-trip as a comment/alias. JSON quoting keeps the
    // round-trip lossless (issue #964 review). Project names are free text
    // too (issue #1941) — same quoting.
    writeIf(authHeader != null, 'authHeader: ${jsonEncode(authHeader)}\n');
    writeIf(project != null, 'project: ${jsonEncode(project)}\n');
    writeIf(
      connectTimeout != null,
      'connectTimeoutMs: ${connectTimeout?.inMilliseconds}\n',
    );
    writeIf(
      streamIdleTimeout != null,
      'streamIdleTimeoutMs: ${streamIdleTimeout?.inMilliseconds}\n',
    );
    writeIf(keyless, 'keyless: true\n');
    return buffer.toString();
  }
}

/// Knobs for the rate-limit retry/fallback engine, mirroring omp's
/// non-compaction retry policy (`retry.*` settings).
final class ModelRolesRetryPolicy {
  /// Creates a retry policy; all values have omp-shaped defaults.
  const ModelRolesRetryPolicy({
    this.retriesPerEntry = 2,
    this.baseDelay = const Duration(milliseconds: 500),
    this.maxBackoff = const Duration(seconds: 8),
    this.maxWait = const Duration(minutes: 5),
    this.maxWaitForLastEntry = const Duration(minutes: 5),
    this.keyBackoff = const Duration(minutes: 1),
  });

  /// Parses the optional `retry:` yaml section.
  factory ModelRolesRetryPolicy.fromYaml(YamlMap map) {
    int? intValue(String key) {
      final value = map[key];
      if (value == null) return null;
      if (value is! int || value < 0) {
        throw ConfigException('"retry.$key" must be a non-negative integer');
      }
      return value;
    }

    Duration? ms(String key) {
      final value = intValue(key);
      return value == null ? null : Duration(milliseconds: value);
    }

    final retries = intValue('retriesPerEntry');
    return ModelRolesRetryPolicy(
      retriesPerEntry: retries ?? 2,
      baseDelay: ms('baseDelayMs') ?? const Duration(milliseconds: 500),
      maxBackoff: ms('maxBackoffMs') ?? const Duration(seconds: 8),
      maxWait: ms('maxWaitMs') ?? const Duration(minutes: 5),
      maxWaitForLastEntry:
          ms('maxWaitForLastEntryMs') ?? const Duration(minutes: 5),
      keyBackoff: ms('keyBackoffMs') ?? const Duration(minutes: 1),
    );
  }

  /// Same-model retries (with backoff) before the run falls to the next
  /// chain entry. Key rotations do not consume this budget (omp switches
  /// credentials for free before spending retries).
  final int retriesPerEntry;

  /// First backoff sleep between same-entry attempts (omp `retry.baseDelayMs`).
  final Duration baseDelay;

  /// Cap on the exponential same-entry backoff (omp caps at 8000 ms).
  final Duration maxBackoff;

  /// Give-up threshold: a required sleep longer than this fails over to the
  /// next chain entry instead of sleeping (omp `retry.maxDelayMs`).
  final Duration maxWait;

  /// Sole-entry wait-out ceiling (issue #1066): when a required retry wait
  /// exceeds [maxWait] and no other chain entry is available to fail over
  /// to, the chain waits out the rate limit anyway — bounded to
  /// `min(delay, maxWaitForLastEntry)` so a pathological `Retry-After`
  /// (hours) still ends the chain.
  final Duration maxWaitForLastEntry;

  /// How long a key (or chain entry) stays in backoff after a rate-limit
  /// failure that carried no `Retry-After` hint.
  final Duration keyBackoff;

  /// Backoff before same-entry attempt [attempt] (1-based): exponential from
  /// [baseDelay], capped at [maxBackoff], with 75–100% jitter (omp's
  /// Anthropic-style jitter so concurrent sessions do not retry in lockstep).
  Duration backoffFor(int attempt, double jitterFraction) {
    var ms = baseDelay.inMilliseconds * (1 << (attempt - 1).clamp(0, 20));
    if (ms > maxBackoff.inMilliseconds) ms = maxBackoff.inMilliseconds;
    final jitter = 0.75 + 0.25 * jitterFraction.clamp(0.0, 1.0);
    return Duration(milliseconds: (ms * jitter).round());
  }

  /// Serializes to yaml (round-trips with [ModelRolesRetryPolicy.fromYaml]).
  String toYaml() {
    return 'retriesPerEntry: $retriesPerEntry\n'
        'baseDelayMs: ${baseDelay.inMilliseconds}\n'
        'maxBackoffMs: ${maxBackoff.inMilliseconds}\n'
        'maxWaitMs: ${maxWait.inMilliseconds}\n'
        'maxWaitForLastEntryMs: ${maxWaitForLastEntry.inMilliseconds}\n'
        'keyBackoffMs: ${keyBackoff.inMilliseconds}\n';
  }
}

/// A path-scoped set of role chains, applied when the cwd matches [pattern].
final class PathRoleOverride {
  /// Creates an override for [pattern] with per-role chains.
  const PathRoleOverride({required this.pattern, required this.roles});

  /// Parses one `modelOverrides` yaml entry.
  factory PathRoleOverride.fromYaml(Object? node) {
    if (node is! YamlMap) {
      throw const ConfigException(
        'modelOverrides entries must be maps with "path" and "roles"',
      );
    }
    final path = node['path'];
    if (path is! String || path.trim().isEmpty) {
      throw const ConfigException(
        'modelOverrides entries require a non-empty "path" string',
      );
    }
    return PathRoleOverride(
      pattern: path.trim(),
      roles: parseRoleChains(node['roles'], source: 'modelOverrides "$path"'),
    );
  }

  /// Absolute path, `~`-rooted path, or glob (`*` matches within a segment,
  /// `**` matches across segments).
  final String pattern;

  /// Role → chain pinned for matching directories.
  final Map<String, List<ModelRef>> roles;

  /// Serializes to yaml (round-trips with [PathRoleOverride.fromYaml]).
  String toYaml() {
    final buffer = StringBuffer()
      ..write('path: $pattern\n')
      ..write('roles:\n');
    buffer.write(_chainsToYaml(roles, indent: 2));
    return buffer.toString();
  }
}

/// Parses a `roles:` map (role name → chain). Shared by the top-level
/// section and [PathRoleOverride]; [source] labels errors.
Map<String, List<ModelRef>> parseRoleChains(Object? node, {String? source}) {
  if (node is! YamlMap) {
    throw ConfigException(
      '${source ?? 'roles'} must be a map of role name to model chain',
    );
  }
  final roles = <String, List<ModelRef>>{
    for (final entry in node.entries)
      _parseRoleName(entry.key, source): _parseRoleChain(
        entry.key as String,
        entry.value,
        source,
      ),
  };
  if (roles.isEmpty) {
    throw ConfigException('${source ?? 'roles'} declares no roles');
  }
  return roles;
}

/// Validates one role key of a `roles:` map; [source] labels errors.
String _parseRoleName(Object? role, String? source) {
  if (role is! String || !modelRoleIds.contains(role)) {
    throw ConfigException(
      'unknown model role "$role"${source == null ? '' : ' in $source'}'
      ' — supported roles: ${modelRoleIds.join(', ')}',
    );
  }
  return role;
}

/// Parses one role's chain (a non-empty list of model references).
List<ModelRef> _parseRoleChain(String role, Object? chainNode, String? source) {
  if (chainNode is! YamlList || chainNode.isEmpty) {
    throw ConfigException(
      '${_roleWhere(role, source)} must be a non-empty list of model references',
    );
  }
  return [
    for (final chainEntry in chainNode)
      ModelRef.fromYaml(chainEntry, role: role),
  ];
}

String _roleWhere(String role, String? source) =>
    source == null ? 'role "$role"' : '$source role "$role"';

String _chainsToYaml(Map<String, List<ModelRef>> roles, {int indent = 0}) {
  final pad = ' ' * indent;
  final buffer = StringBuffer();
  for (final role in modelRoleIds) {
    final chain = roles[role];
    if (chain == null) continue;
    buffer.write('$pad$role:\n');
    for (final ref in chain) {
      final lines = ref.toYaml().trimRight().split('\n');
      buffer.write('$pad  - ${lines.first}\n');
      for (final line in lines.skip(1)) {
        buffer.write('$pad    $line\n');
      }
    }
  }
  return buffer.toString();
}

/// Whether [pattern] matches the working directory [cwd].
///
/// Semantics (omp's scoped entries, extended with globs per the card):
///
/// - a `~` prefix expands against [homeDir] (pass it explicitly; this library
///   is pure Dart and never reads the environment itself);
/// - a pattern containing `*` is a glob: `*` matches any run of non-`/`
///   characters, `**` matches anything (including `/`);
/// - any other pattern is a path prefix: it matches the cwd itself and any
///   of its subdirectories.
///
/// Matching is lexical (no filesystem access); redundant trailing slashes
/// are stripped. The cwd should be absolute.
bool pathPatternMatches(String pattern, String cwd, {String? homeDir}) {
  final pat = _normalizePattern(pattern, homeDir);
  if (pat == null) return false;
  final dir = stripTrailingSlashes(cwd.trim());
  if (pat.isEmpty || dir.isEmpty) return false;

  if (pat.contains('*')) {
    return _globPatternMatches(pat, dir);
  }

  return dir == pat || dir.startsWith('$pat/');
}

/// Trims [pattern] and expands a `~` prefix against [homeDir] (pass it
/// explicitly; this library is pure Dart and never reads the environment
/// itself). Returns `null` when the pattern needs a home directory that was
/// not provided.
String? _normalizePattern(String pattern, String? homeDir) {
  var pat = pattern.trim();
  if (pat.startsWith('~')) {
    if (homeDir == null) return null;
    pat = pat.length == 1 ? homeDir : '$homeDir${pat.substring(1)}';
  }
  return stripTrailingSlashes(pat);
}

/// Whether the glob [pattern] (`*` matches any run of non-`/` characters,
/// `**` matches anything, including `/`) matches [dir] lexically.
bool _globPatternMatches(String pattern, String dir) {
  final regex = StringBuffer('^');
  for (var i = 0; i < pattern.length; i++) {
    final char = pattern[i];
    if (char == '*') {
      final doubleStar = i + 1 < pattern.length && pattern[i + 1] == '*';
      regex.write(doubleStar ? '.*' : '[^/]*');
      if (doubleStar) i++;
    } else {
      regex.write(RegExp.escape(char));
    }
  }
  regex.write(r'$');
  return RegExp(regex.toString()).hasMatch(dir);
}

/// Model-role configuration: role → ordered fallback chains, path-scoped
/// overrides, and the retry policy.
final class ModelRolesConfig {
  /// Creates a config; [roles] maps role id to its ordered chain.
  /// [runtimePinned] names the roles pinned by a LIVE session decision
  /// (`/provider` / `/model`) — see the field docs; yaml parsing never
  /// pins (a config file cannot pre-empt a runtime switch).
  ModelRolesConfig({
    required Map<String, List<ModelRef>> roles,
    this.pathOverrides = const [],
    this.retry = const ModelRolesRetryPolicy(),
    Set<String> runtimePinned = const <String>{},
  }) : roles = Map.unmodifiable({
         for (final entry in roles.entries)
           entry.key: List<ModelRef>.unmodifiable(entry.value),
       }),
       runtimePinned = Set.unmodifiable(runtimePinned);

  /// Parses the `roles:` / `modelOverrides:` / `retry:` sections of the CLI
  /// config. Strict: any schema problem throws [ConfigException] (a corrupt
  /// roles section must surface, never silently reset to defaults).
  factory ModelRolesConfig.fromYaml(YamlMap map) {
    final rolesNode = map['roles'];
    if (rolesNode == null) {
      throw const ConfigException('no "roles" section in config');
    }
    final roles = parseRoleChains(rolesNode);

    final overridesNode = map['modelOverrides'];
    final overrides = <PathRoleOverride>[];
    if (overridesNode != null) {
      if (overridesNode is! YamlList) {
        throw const ConfigException('"modelOverrides" must be a list');
      }
      for (final entry in overridesNode) {
        overrides.add(PathRoleOverride.fromYaml(entry));
      }
    }

    final retryNode = map['retry'];
    if (retryNode != null && retryNode is! YamlMap) {
      throw const ConfigException('"retry" must be a map of retry settings');
    }
    final retry = retryNode == null
        ? const ModelRolesRetryPolicy()
        : ModelRolesRetryPolicy.fromYaml(retryNode);

    return ModelRolesConfig(
      roles: roles,
      pathOverrides: overrides,
      retry: retry,
    );
  }

  /// Role id → ordered fallback chain (first entry is primary).
  final Map<String, List<ModelRef>> roles;

  /// Path-scoped role chains, most-specific match wins.
  final List<PathRoleOverride> pathOverrides;

  /// Retry/fallback knobs.
  final ModelRolesRetryPolicy retry;

  /// Role ids pinned by a LIVE session decision — the runtime
  /// `/provider` / `/model` switch (`ModelRolesResolver.setRoleChain`,
  /// gh-2433). A pinned role's chain skips the [pathOverrides] step:
  /// the switch must out-rank every path override, or the longest-match
  /// entry silently resurrects the config chain over the user's decision
  /// (the Copilot switch that kept running on Bedrock). Runtime state —
  /// never parsed from, or serialized to, yaml.
  final Set<String> runtimePinned;

  /// Resolves [role]'s chain for the working directory [cwd].
  ///
  /// Resolution order (mirroring omp):
  ///
  /// 1. the longest matching [pathOverrides] pattern that pins [role] —
  ///    SKIPPED for a [runtimePinned] role (gh-2433: the runtime switch
  ///    wins over every path override);
  /// 2. the top-level [roles] chain for [role];
  /// 3. for non-default roles, the `default` role's chain (omp's
  ///    inherit-default-before-priority behavior);
  /// 4. `null` when nothing applies (the caller falls back to its legacy
  ///    single-model wiring).
  List<ModelRef>? chainFor(String role, {String? cwd, String? homeDir}) {
    if (!modelRoleIds.contains(role)) {
      throw ConfigException(
        'unknown model role "$role" — supported roles: '
        '${modelRoleIds.join(', ')}',
      );
    }
    if (cwd != null && !runtimePinned.contains(role)) {
      final matching =
          pathOverrides
              .where(
                (override) =>
                    override.roles.containsKey(role) &&
                    pathPatternMatches(override.pattern, cwd, homeDir: homeDir),
              )
              .toList()
            ..sort((a, b) => b.pattern.length.compareTo(a.pattern.length));
      if (matching.isNotEmpty) return matching.first.roles[role];
    }
    return roles[role] ??
        (role == defaultModelRole ? null : roles[defaultModelRole]);
  }

  /// Whether [role] resolves EXPLICITLY for [cwd] — a top-level chain or a
  /// matching [pathOverrides] pattern ([chainFor]'s steps 1–2) — rather
  /// than through the inherit-default step. Callers distinguish "the user
  /// configured this role here" from "the role rides the default chain":
  /// a subagent keeps the parent's live wiring (its runtime-resolved
  /// output-cap ladder entry) unless its role is genuinely pinned
  /// (issue #302).
  bool pinsRole(String role, {String? cwd, String? homeDir}) {
    if (roles.containsKey(role)) return true;
    if (cwd == null) return false;
    return pathOverrides.any(
      (override) =>
          override.roles.containsKey(role) &&
          pathPatternMatches(override.pattern, cwd, homeDir: homeDir),
    );
  }

  /// Serializes to the `roles:` / `modelOverrides:` / `retry:` yaml sections
  /// (round-trips with [ModelRolesConfig.fromYaml]).
  String toYaml() {
    final buffer = StringBuffer()
      ..write('roles:\n')
      ..write(_chainsToYaml(roles, indent: 2));
    if (pathOverrides.isNotEmpty) {
      buffer.write('modelOverrides:\n');
      for (final override in pathOverrides) {
        final lines = override.toYaml().trimRight().split('\n');
        buffer.write('  - ${lines.first}\n');
        for (final line in lines.skip(1)) {
          buffer.write('    $line\n');
        }
      }
    }
    buffer
      ..write('retry:\n')
      ..write(
        retry
            .toYaml()
            .trimRight()
            .split('\n')
            .map((line) => '  $line\n')
            .join(),
      );
    return buffer.toString();
  }
}

/// Runtime resolution for model roles: turns a [ModelRolesConfig] plus a
/// secrets snapshot into per-role [FallbackStreamFunction]s, and applies
/// roles to an [Agent].
///
/// This is the consumer surface of the model-roles feature:
///
/// - the agent gets a role per run via [applyToAgent] (hosts default to
///   `default`; the role decides model + stream for the run);
/// - compaction summarization resolves through `smol` via [resolveRole] when
///   that role is configured (cheap summaries), else the caller keeps its
///   legacy model;
/// - `/model` renders [describeRoles].
///
/// Chain entries whose API key is absent from the secrets snapshot are
/// skipped (omp ignores uncredentialed fallback targets) and reported in
/// [skippedEntries]; a role whose chain resolves to nothing throws the
/// degradable [UnusableRoleChainException] (gh-1570: never a plain boot
/// exit on a recoverable config).
library;

import '../agent/agent.dart';
import '../agent/agent_loop.dart';
import '../cancel_token.dart';
import '../exceptions.dart';
import '../model.dart';
import '../secrets/secrets_store.dart';
import '../cli/custom_providers.dart'
    show CustomProviderEntry, CustomProviderRegistry, sameEndpoint;
import 'fallback_stream.dart';
import 'key_rotation.dart';
import 'roles_config.dart';
import 'provider_catalog.dart';
import '../providers/silent_stream_policy.dart';
import '../providers/transient_retry_stream.dart' show transientRetryNotice;

/// gh-760 (review): the role's chain has NO usable entry. The boot
/// boundary degrades THIS shape to the legacy single-model path with a
/// loud, named warning — never process exit. gh-1570 (incident
/// 2026-10-12) generalized the contract: a recoverable aggregate (every
/// entry missing its key — set it with `/key set`, reboot, repaired) is
/// the same degrade, because hard-exiting the binary locks the user out
/// of the tool exactly when they need it to repair the config. Known
/// subclasses mark WHY the chain died; the boot treats them identically.
final class UnusableRoleChainException extends ConfigException {
  /// Creates the exception with the joined skip reasons.
  const UnusableRoleChainException(super.message);
}

/// gh-760 (review): the role's chain has NO usable entry AND the skip
/// reasons include unknown providers — a config written by a newer
/// app/CLI version. A typed subtype of the degradable
/// [UnusableRoleChainException] so callers can still distinguish
/// version skew from a current-version recoverable gap; the boot
/// degrades both identically (the drop is whole-resolver BY DESIGN —
/// gh-760 review: the per-turn main-model path re-enters chainFor, so a
/// half-alive resolver would move the failure to mid-session).
final class UnknownProviderRoleException extends UnusableRoleChainException {
  /// Creates the exception with the joined skip reasons.
  const UnknownProviderRoleException(super.message);
}

/// Builds per-role fallback chains from configuration and secrets.
final class ModelRolesResolver {
  /// Creates a resolver over [config] and a snapshot of [secrets]
  /// (name → value). [cwd]/[homeDir] feed path-override matching;
  /// [now]/[jitterFraction]/[sleeper] are injectable for deterministic
  /// tests and forwarded to every chain wrapper. [streamFactory] builds the
  /// per-key provider adapter (defaults to [providerStreamFunction]; tests
  /// inject fakes).
  ModelRolesResolver({
    required this.config,
    required Map<String, String> secrets,
    this.customProviders = const [],
    this.cwd,
    this.homeDir,
    this.onNotice,
    DateTime Function()? now,
    this.jitterFraction,
    this.sleeper,
    StreamFunction Function(String kind, String apiKey)? streamFactory,
  }) : _secrets = Map.unmodifiable(secrets),
       _now = now ?? DateTime.now,
       _streamFactory = streamFactory ?? providerStreamFunction;

  /// Builds a resolver from a [SecretsStore] (reads the bulk snapshot once).
  static Future<ModelRolesResolver> fromSecretsStore(
    ModelRolesConfig config,
    SecretsStore store, {
    String? cwd,
    String? homeDir,
    void Function(FallbackNotice notice)? onNotice,
    DateTime Function()? now,
    double Function()? jitterFraction,
    Future<bool> Function(Duration delay, CancelToken? cancelToken)? sleeper,
    StreamFunction Function(String kind, String apiKey)? streamFactory,
  }) async {
    return ModelRolesResolver(
      config: config,
      secrets: await store.readAll(),
      cwd: cwd,
      homeDir: homeDir,
      onNotice: onNotice,
      now: now,
      jitterFraction: jitterFraction,
      sleeper: sleeper,
      streamFactory: streamFactory,
    );
  }

  /// The active configuration (replaced by [setDefaultChain]).
  ModelRolesConfig config;

  /// The saved custom providers (the `customProviders:` config section) —
  /// the registry leg of chain-name resolution (issue #1552): a chain
  /// entry naming one of these entries (`provider: aiai`) resolves through
  /// the entry's apiType spec, with the entry's `baseUrl`/`keyName` as
  /// defaults where the ref omits them. Empty (default) = the legacy
  /// catalog-only surface; nothing existing changes shape.
  final List<CustomProviderEntry> customProviders;

  /// The working directory used for path-override matching.
  final String? cwd;

  /// Home directory for `~` override patterns.
  final String? homeDir;

  /// Receives every chain wrapper's [FallbackNotice]. Mutable so hosts can
  /// attach rendering after construction; wrappers forward to the current
  /// value.
  void Function(FallbackNotice notice)? onNotice;

  /// Cache-affinity session id bound into every chain entry's provider
  /// stream (resolved lazily per call, so a host that learns the session id
  /// after construction — the CLI/app create sessions lazily — still gets
  /// prompt-cache affinity). Ignored for adapters without cache routing.
  String? Function()? sessionId;

  /// Jitter source forwarded to chain wrappers (tests inject determinism).
  final double Function()? jitterFraction;

  /// Sleep implementation forwarded to chain wrappers (tests inject fakes).
  final Future<bool> Function(Duration delay, CancelToken? cancelToken)?
  sleeper;

  Map<String, String> _secrets;
  final DateTime Function() _now;
  final StreamFunction Function(String kind, String apiKey) _streamFactory;
  final _rings = <String, ApiKeyRing>{};
  final _wrappers = <String, FallbackStreamFunction>{};

  /// Registers an additional secret at runtime — a key typed into a
  /// provider wizard while the session runs. The constructor's snapshot is
  /// immutable by design, so this swaps in an extended copy and drops the
  /// cached key rings and chain wrappers: the next run re-resolves with the
  /// new secret available.
  void addSecret(String name, String value) {
    _secrets = Map.unmodifiable({..._secrets, name: value});
    _rings.clear();
    _wrappers.clear();
  }

  /// Chain entries skipped during the last [chainFor] per role, as
  /// `provider/modelId (reason)` — resolution must not degrade silently.
  final skippedEntries = <String, List<String>>{};

  /// Resolves [role]'s chain for [cwd] and builds the entries (models from
  /// the provider catalog, key rings from the secrets snapshot).
  ///
  /// Returns `null` when neither [role] nor the inherited `default` role is
  /// configured (the caller keeps its legacy single-model wiring).
  List<ChainEntry>? chainFor(String role) {
    final refs = config.chainFor(role, cwd: cwd, homeDir: homeDir);
    if (refs == null) return null;
    final skipped = skippedEntries[role] = <String>[];
    final entries = <ChainEntry>[];
    // Typed version-skew marker (gh-760 review): classification NEVER
    // substring-matches the human-readable skip reasons — those embed
    // user-controlled text (provider/modelId labels).
    var sawUnknownProvider = false;
    for (final ref in refs) {
      final entry = _buildEntry(
        ref,
        skipped,
        role: role,
        onUnknownProvider: () => sawUnknownProvider = true,
      );
      if (entry != null) entries.add(entry);
    }
    if (entries.isEmpty) {
      final message =
          'role "$role" has no usable chain entry: ${skipped.join('; ')}';
      // gh-760: degrade, never brick. Unknown providers (a config written
      // by a newer app/CLI) throw the dedicated version-skew subtype.
      // gh-1570 (incident 2026-10-12): a chain of KNOWN providers merely
      // missing keys degrades TOO — the same degradable base, never a
      // plain ConfigException: the boot must not process-exit on a
      // condition a `/key set` repairs (the old pre-#760 loud-failure
      // stance locked the user out of the repair tool itself).
      throw sawUnknownProvider
          ? UnknownProviderRoleException(message)
          : UnusableRoleChainException(message);
    }
    return entries;
  }

  ChainEntry? _buildEntry(
    ModelRef ref,
    List<String> skipped, {
    required String role,
    required void Function() onUnknownProvider,
  }) {
    // gh-760 (review): resolve by catalog name AND adapter kind — a roles
    // entry written as a kind (`chatgpt-codex`, exactly what the app
    // writes) is KNOWN to this version and must not be skipped as unknown.
    // honorBuildFilter: roles are a user-facing surface — the filter the
    // old name-only + kind-loop pair applied, now in the one seam.
    var spec = resolveCliProviderSpec(ref.provider, honorBuildFilter: true);
    if (spec == null) {
      // Issue #1552: the catalog missed — a hand-written config may name
      // a `customProviders:` entry (`provider: aiai`). The registry leg
      // (_registryLeg) resolves through the entry; null = the gh-760 skip
      // is already reported and classified there — degrade now. The
      // reserved-name rule (isReservedCustomProviderName) bars registry
      // entries from catalog names, so the leg only ever answers what
      // the catalog missed — the two namespaces never shadow.
      final viaRegistry = _registryLeg(
        ref,
        skipped,
        onUnknownProvider: onUnknownProvider,
      );
      if (viaRegistry == null) return null;
      (ref, spec) = viaRegistry;
    }
    // Non-null alias: the registry leg reassigns `spec` above and
    // `buildRouted` below captures it — flow analysis never promotes a
    // captured local that is assigned more than once, so the closure must
    // read a final.
    final resolvedSpec = spec;
    // gh-1570 (AC8): a keyless ref needs NO credential — a localhost
    // bench endpoint or an unauthenticated gateway. The check PREEMPTS
    // key discovery: no env name is probed, and the stream factory
    // receives the EMPTY key, byte-parity with the non-roles keyless
    // boot (a saved config's stray key never leaks onto the pin).
    final ApiKeyRing ring;
    if (ref.keyless) {
      ring = ApiKeyRing(
        baseName: '',
        credentials: const [ApiKeyCredential('', '')],
      );
    } else {
      final keyBase = _keyBaseName(ref, resolvedSpec);
      if (keyBase == null) {
        skipped.add(
          '${ref.label} (missing API key: ${_missingKeyHint(ref, resolvedSpec)})',
        );
        return null;
      }
      ring = _rings.putIfAbsent(
        keyBase,
        () => ApiKeyRing.fromSecrets(_secrets, keyBase, now: _now)!,
      );
    }
    // gh-1395 review round 1: ONE policy per chain entry (session-scoped).
    // streamForKey is invoked per fallback ATTEMPT; building the policy
    // inside it would mint a fresh ledger every attempt and AC4/E3's
    // cross-call escalation (5→10→20 s, rotation, takeover) could never
    // happen. Memoized here: the ledger survives across attempts AND
    // calls; `currentKey` re-binds on every streamForKey so the fallback's
    // own credential choice (affinity/rate-limit rotation) is honored,
    // and [buildRouted] re-reads it per attempt so a rotation rebinds.
    SilentStreamPolicy? entryPolicy;
    var currentKey = ring.currentCredential.value;

    StreamFunction buildRouted() {
      final inner = _streamFactory(resolvedSpec.kind, currentKey);
      return (model, context, {cancelToken}) {
        // An explicit per-call override (the compaction bypass) wins
        // over the resolver's bound session id. GOAL #2394: an all-null
        // override (the session-affine hand-over fallthrough) is no
        // opinion — the resolver's binding stands, so the call rides the
        // session's own cache bucket.
        if (StreamCacheRouting.hasExplicitRouting) {
          return inner(model, context, cancelToken: cancelToken);
        }
        return StreamCacheRouting.runWith(
          () => inner(model, context, cancelToken: cancelToken),
          // Read the mutable field lazily: hosts learn the session id
          // after the resolver (and its chains) were built.
          sessionId: sessionId?.call(),
        );
      };
    }

    return ChainEntry(
      // Build from the RESOLVED spec's name: a kind-named ref
      // (`chatgpt-codex`) is not itself a catalog key.
      model: buildCatalogModel(
        resolvedSpec.name,
        ref.modelId,
        baseUrl: ref.baseUrl,
        contextWindow: ref.contextWindow,
        maxTokens: ref.maxTokens,
        input: ref.input,
        thinkingLevel: ref.thinkingLevel,
        authHeader: ref.authHeader,
        // The chain SERVES from this entry — the CodeMie project must ride
        // it or every chain request bills the DEFAULT project (issue
        // #1941; same shape as the authHeader leg, issue #964).
        projectHeader: ref.project,
        // Request-scoped watchdog windows (issue #1554): the chain
        // entry's own fields are the TOP precedence layer, riding the
        // model — the streams of this role (and only this role) watch
        // under its windows even when another entry shares the endpoint.
        connectTimeout: ref.connectTimeout,
        streamIdleTimeout: ref.streamIdleTimeout,
        timeoutScopeLabel:
            ref.connectTimeout == null && ref.streamIdleTimeout == null
            ? null
            : 'role $role override',
      ),
      keyRing: ring,
      streamForKey: (apiKey) {
        currentKey = apiKey;
        final policy = entryPolicy ??= SilentStreamPolicy(
          innerBuilder: buildRouted,
          hooks: SilentStreamPolicyHooks(
            rotateKey: () {
              final rotated = rotateRingPast(ring, currentKey);
              if (rotated) {
                // rotate() advanced the ring's affinity — the new
                // current credential is the one the next attempt uses.
                currentKey = ring.currentCredential.value;
              }
              return rotated;
            },
            buildTakeover: role == smolModelRole ? null : _smolTakeoverStream,
            onNotice: (note) =>
                transientRetryNotice?.call(0, 1, Duration.zero, note),
          ),
          sleeper: sleeper,
        );
        // gh-1395 (AC4): every chain entry's stream rides the
        // SilentStreamPolicy — a PRE-commit idle stall gets the bounded,
        // escalating ladder (backoff 5→60s, key rotation on the ring after
        // the 2nd stall of the run, smol-role takeover attempt after the
        // 3rd) instead of a blind same-upstream replay (bench recovery
        // 1/13). Non-stall classes pass through untouched: transport
        // failures still replay in the transient ladder, rate limits still
        // rotate in the roles ladder, and the policy never replays
        // post-commit content (#964).
        return policy.call;
      },
    );
  }

  /// Rotates [ring] past the credential whose VALUE is [currentValue] —
  /// translated to its secrets-store NAME first, because `ApiKeyRing
  /// .rotate` matches by name and a raw value never matches (review round
  /// 1). `false` for a single-key ring (E5: the policy logs the skip and
  /// retries the same credential) or when every key is benched.
  static bool rotateRingPast(ApiKeyRing ring, String currentValue) {
    if (ring.length <= 1) return false;
    final current = ring.credentialByValue(currentValue);
    final next = ring.rotate(current?.name ?? ring.currentCredential.name);
    return next != null;
  }

  /// The registry LEG of chain-name resolution (issue #1552): the catalog
  /// missed [ref]'s provider, so resolve through the saved
  /// `customProviders:` entries. A matched entry resolves through its
  /// apiType's catalog spec (the same honorBuildFilter rule every
  /// user-facing roles surface applies), with the entry's
  /// `baseUrl`/`keyName` as defaults where the ref omits them (explicit
  /// ref fields always win). Returns the defaulted ref paired with its
  /// spec, or null with the gh-760 skip ALREADY reported to [skipped] and
  /// classified via [onUnknownProvider] — the caller just degrades:
  ///
  /// - no entry matches → a name known to NEITHER namespace (gh-760): the
  ///   generic unknown-provider skip, as before this leg existed;
  /// - the matched entry's apiType is unknown to this version (a saved
  ///   entry written by a newer CLI) → an unknown ADAPTER DIALECT skip —
  ///   the registry entry IS known, only its dialect isn't, so "unknown
  ///   provider" would send the user hunting an entry spelling that is
  ///   fine.
  ///
  /// Both paths keep the degrade contract: a named skip reason, never a
  /// throw, so the remaining known entries carry the role.
  (ModelRef, ProviderSpec)? _registryLeg(
    ModelRef ref,
    List<String> skipped, {
    required void Function() onUnknownProvider,
  }) {
    final entry = _findCustomProvider(ref.provider);
    if (entry == null) {
      skipped.add('${ref.label} (unknown provider: ${ref.provider})');
      onUnknownProvider();
      return null;
    }
    final spec = resolveCliProviderSpec(entry.apiType, honorBuildFilter: true);
    if (spec != null) return (_throughCustomEntry(ref, entry), spec);
    skipped.add('${ref.label} (unknown adapter dialect: ${entry.apiType})');
    onUnknownProvider();
    return null;
  }

  /// The saved custom entry named by a chain ref (case-insensitive), or
  /// null — the registry leg of the resolver's name resolution (issue
  /// #1552). No alias canonicalization here: chain refs are hand-written
  /// names, and the registry's own load merge already folded alias twins.
  CustomProviderEntry? _findCustomProvider(String name) {
    final lower = name.trim().toLowerCase();
    for (final entry in customProviders) {
      if (entry.name.toLowerCase() == lower) return entry;
    }
    return null;
  }

  /// Defaults [ref]'s pin fields from the custom entry the ref named
  /// (issue #1552): the entry supplies `baseUrl`, `keyName` and the CodeMie
  /// project (issue #1941) where the ref omits them; explicit ref fields
  /// always win. Every other field
  /// (model, window/token/modality/thinking/auth-header/tuning overrides)
  /// is the ref's own, exactly as for a kind+baseUrl entry.
  ModelRef _throughCustomEntry(ModelRef ref, CustomProviderEntry entry) {
    if (ref.baseUrl != null && ref.apiKeyName != null) return ref;
    return ModelRef(
      provider: ref.provider,
      modelId: ref.modelId,
      apiKeyName: ref.apiKeyName ?? entry.keyName,
      baseUrl: ref.baseUrl ?? entry.baseUrl,
      contextWindow: ref.contextWindow,
      maxTokens: ref.maxTokens,
      input: ref.input,
      thinkingLevel: ref.thinkingLevel,
      authHeader: ref.authHeader,
      // The registry leg must not drop the project (issue #1941): a ref
      // naming the saved entry inherits its pick — a header-less rebuild
      // here re-attributed chain traffic to the DEFAULT project.
      project: ref.project ?? entry.project,
      connectTimeout: ref.connectTimeout,
      streamIdleTimeout: ref.streamIdleTimeout,
      // gh-1570 (AC8): a keyless ref routed through a custom entry keeps
      // its keyless flag — the rebuild must not reset it to false and
      // send the resolver probing for a credential the endpoint never
      // takes.
      keyless: ref.keyless,
    );
  }

  /// The key base name for [ref]: its explicit `apiKeyName`, else — for a
  /// chain entry pinned to a CUSTOM endpoint — the endpoint-scoped
  /// `FA_KEY_<HOST>` slot (the same source a manual provider switch
  /// resolves; gh-1000 AC5), else the first of the provider's env names
  /// present in the secrets snapshot. `null` when no candidate resolves
  /// to a configured key.
  String? _keyBaseName(ModelRef ref, ProviderSpec spec) {
    final explicit = ref.apiKeyName;
    if (explicit != null) {
      if (collectKeyStack(_secrets, explicit).isNotEmpty) return explicit;
      // gh-1570 incident REG: the pin NAMES a slot, but a derivation
      // change across versions can leave the key under the previous
      // release's name (the 1.0.556 → 1.0.564 lockout: the record-scoped
      // pin went unpopulated while the key sat on the host-scoped slot).
      // The pin stays first choice; an empty pin falls back to the
      // endpoint's own slot family (canonical + host-scoped) before the
      // ref is declared key-missing.
      return _firstConfigured(ref, spec) ?? _missingPinFallback(ref);
    }
    return _firstConfigured(ref, spec);
  }

  /// The endpoint-scoped candidate slots (gh-1570 cross-version set,
  /// canonical first) probed when a ref's explicit pin is EMPTY: the pin's
  /// own endpoint family, regardless of whether the endpoint is the
  /// catalog default (the incident pin sat on kimi's default URL).
  String? _missingPinFallback(ModelRef ref) {
    final baseUrl = ref.baseUrl;
    if (baseUrl == null) return null;
    for (final scoped in CustomProviderRegistry.keySlotCandidates(baseUrl)) {
      if (collectKeyStack(_secrets, scoped).isNotEmpty) return scoped;
    }
    return null;
  }

  /// The pre-gh-1570 resolution order for an unpinned ref: the
  /// endpoint-scoped slots (cross-version set), then the provider's env
  /// names — the first base with a configured key wins.
  String? _firstConfigured(ModelRef ref, ProviderSpec spec) {
    for (final scoped in _endpointScopedKeyNames(ref, spec)) {
      if (collectKeyStack(_secrets, scoped).isNotEmpty) return scoped;
    }
    for (final candidate in spec.apiKeyEnvNames) {
      if (collectKeyStack(_secrets, candidate).isNotEmpty) return candidate;
    }
    return null;
  }

  /// The endpoint-scoped `FA_KEY_<HOST>` slot names for a chain entry
  /// pinned to a non-default endpoint, canonical first — else empty. The
  /// snapshot carries every cross-spelling slot's value when the host
  /// collected them (the startup snapshot preloads the same set —
  /// gh-1000, gh-1570).
  List<String> _endpointScopedKeyNames(ModelRef ref, ProviderSpec spec) {
    final baseUrl = ref.baseUrl;
    // Trailing-slash-normalized (the shared sameEndpoint rule): a default
    // endpoint saved with a trailing slash must not mint a bogus scoped
    // slot — one endpoint-equality rule with key_status (round-3 review).
    if (baseUrl == null || sameEndpoint(baseUrl, spec.defaultBaseUrl)) {
      return const [];
    }
    return CustomProviderRegistry.keySlotCandidates(baseUrl);
  }

  /// The canonical endpoint-scoped slot for [ref] — the name the
  /// missing-key hint tells the user to set (the fix-it target), not the
  /// whole fallback set.
  String? _endpointScopedKeyName(ModelRef ref, ProviderSpec spec) =>
      _endpointScopedKeyNames(ref, spec).firstOrNull;

  /// The missing-key hint for [ref]'s skip reason: an explicitly pinned
  /// `apiKeyName` names THAT slot (the only name that would resolve it —
  /// the endpoint-scoped default would be wrong-slot guidance, gh-1000
  /// AC2), a custom endpoint names its `/key set` fix (the catalog env
  /// name would point at the DEFAULT endpoint — the wrong slot, gh-1000
  /// AC2/AC5), a default endpoint names its env var.
  String _missingKeyHint(ModelRef ref, ProviderSpec spec) {
    final explicit = ref.apiKeyName;
    if (explicit != null) {
      return '/key set $explicit <value>';
    }
    final scopedName = _endpointScopedKeyName(ref, spec);
    if (scopedName != null) {
      return '/key set $scopedName <value>';
    }
    return 'set ${spec.apiKeyEnvNames.first}';
  }

  /// The cached [FallbackStreamFunction] for [role] (entry cooldowns and
  /// chain position persist across runs — session state).
  FallbackStreamFunction streamForRole(String role) {
    return _wrappers.putIfAbsent(role, () {
      final entries = chainFor(role);
      if (entries == null) {
        throw ConfigException('role "$role" is not configured');
      }
      return FallbackStreamFunction(
        entries: entries,
        policy: config.retry,
        onNotice: (notice) => onNotice?.call(notice),
        now: _now,
        jitterFraction: jitterFraction,
        sleeper: sleeper,
      );
    });
  }

  /// The smol-role takeover stream, or `null` when smol is not configured
  /// (the policy logs the skip; the stall error stands). Runs at ESCALATION
  /// time (the 3rd stall), never at entry build. Split out of
  /// [_buildEntry]'s takeover closure (CRAP ratchet): the catch-clause
  /// line is never credited by the VM's coverage instrumentation even when
  /// the handler runs — at CC 12 that read as one permanently-uncovered
  /// line → CRAP 12.0008 > the 12.0 ratchet, unfixable by tests in place.
  StreamFunction? _smolTakeoverStream() {
    try {
      final smolWrapper = streamForRole(smolModelRole);
      final smolModel = smolWrapper.currentModel;
      return (model, context, {cancelToken}) =>
          smolWrapper.call(smolModel, context, cancelToken: cancelToken);
    } on ConfigException {
      return null; // smol not configured (logged by the policy)
    }
  }

  /// Resolves [role] to its current model and stream function, or `null`
  /// when the role (and the inherited `default`) is unconfigured.
  ({Model model, StreamFunction stream})? resolveRole(String role) {
    if (config.chainFor(role, cwd: cwd, homeDir: homeDir) == null) {
      return null;
    }
    final wrapper = streamForRole(role);
    return (model: wrapper.currentModel, stream: wrapper.call);
  }

  /// Points [agent] at [role]'s model and fallback stream for subsequent
  /// runs (the agent's role for a run; hosts use `default` for user turns).
  void applyToAgent(Agent agent, {String role = defaultModelRole}) {
    final wrapper = streamForRole(role);
    agent.streamFunction = wrapper.call;
    agent.state.model = wrapper.currentModel;
  }

  /// Replaces the `default` role's chain (runtime `/model <id>` switch);
  /// the new chain takes effect on the next run.
  void setDefaultChain(List<ModelRef> chain) {
    setRoleChain(defaultModelRole, chain);
  }

  /// Replaces [role]'s chain (the settings-hub agent-models flow); the new
  /// chain takes effect on the next run. The role is [ModelRolesConfig
  /// .runtimePinned] so its chain beats every path override — a runtime
  /// switch must never be silently out-voted by the longest-match entry
